"use strict";
// No token, auth URL, or secret is placed in localStorage/sessionStorage or browser logs.
const $ = (id) => document.getElementById(id);
let catalog=[],active=null,selected=null,tokenInfo=null;
function node(tag, text, cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function setMsg(msg,bad=false){$('message').textContent=msg;$('message').style.color=bad?'#ff9b9b':'#98deb3';}
async function json(url, init){const r=await fetch(url,{cache:'no-store',credentials:'same-origin',...init});let body;try{body=await r.json();}catch{body={};}if(!r.ok)throw Error(body.error||'Request failed ('+r.status+')');return body;}
async function refresh(){const [list,token]=await Promise.all([json('/api/brokers/catalog'),json('/api/token')]);catalog=list.brokers||[];active=list.active;tokenInfo=token;
  $('count').textContent=catalog.length+' registered';$('banner').textContent='Active broker: '+(catalog.find(x=>x.name===active)?.label||'Not selected')+'. Only that broker can authenticate in the current session. Switching brokers requires a service restart.';
  if(!selected||!catalog.some(x=>x.name===selected))selected=active||catalog[0]?.name;draw();}
function draw(){const grid=$('cards');grid.replaceChildren();for(const b of catalog){const btn=node('button',undefined,'broker'+(selected===b.name?' chosen':''));btn.type='button';btn.append(node('span',b.label,'bname'),node('span',b.status,'bmeta'),node('span',b.active?'Active session':'Available adapter','pill'+(b.active?' live':'')));btn.onclick=()=>{selected=b.name;draw();};grid.append(btn);}
const b=catalog.find(x=>x.name===selected);if(!b)return;$('detail-name').textContent=b.label;$('detail-description').textContent='Broker adapter: '+b.name+' · '+b.token_expiry_rule;
$('detail-status').textContent='Adapter: '+b.status;$('detail-active').textContent=b.active?'● Active':'○ Inactive';
const keys=$('keys');keys.replaceChildren();for(const name of b.setup_keys||[]){const line=node('div',undefined,'key');line.append(node('span',name));const cp=node('button','Copy','secondary');cp.onclick=()=>navigator.clipboard.writeText(name+'=');line.append(cp);keys.append(line);}keys.append(node('div','Daily token field: '+b.token_key,'key'));
$('stage').hidden=b.active;$('stage-warning').hidden=true;$('login-panel').hidden=!b.active;$('login-status').textContent=b.active?'Use only credentials issued to your own account. The application validates tokens before saving.':'Choose this broker for the next restart, then configure its .env fields before logging in.';
if(b.active){$('login-link').hidden=!(tokenInfo.client_login&&tokenInfo.client_login.login_url);if(tokenInfo.client_login?.login_url){const u=tokenInfo.client_login.login_url;try{const link=new URL(u);if(link.protocol==='https:'){$('login-link').href=u;$('login-link').hidden=false;}}catch{}}
const fields=tokenInfo.client_login?.fields||[];$('login-form').hidden=!fields.length;$('login-fields').replaceChildren();for(const key of fields){const label=node('label',key);const input=node('textarea');input.required=true;input.autocomplete='off';input.name=key;input.spellcheck=false;input.rows=2;label.append(input);$('login-fields').append(label);}
const v=tokenInfo.token_masked?'Token stored (masked)':'No saved token reported';$('login-status').textContent=v+'. '+$('login-status').textContent;}}
$('stage').onclick=async()=>{const b=catalog.find(x=>x.name===selected);if(!b||b.active)return;if(!confirm('Stage '+b.label+' as BROKER in .env? Current FYERS session keeps running until you stop/restart the application. A backup is created.'))return;
try{await json('/api/brokers/stage',{method:'POST',headers:{'Content-Type':'application/json','X-Gamma-Control':'1'},body:JSON.stringify({broker:b.name})});$('stage-warning').hidden=false;setMsg('Broker selection staged. Restart GAMMA-UNWIND to activate '+b.label+'.');}catch(e){setMsg(e.message,true);}};
$('login-form').onsubmit=async(e)=>{e.preventDefault();const fields={};for(const inp of $('login-form').querySelectorAll('textarea'))fields[inp.name]=inp.value.trim();try{await json('/api/token/login',{method:'POST',headers:{'Content-Type':'application/json','X-Gamma-Control':'1'},body:JSON.stringify({fields})});for(const inp of $('login-form').querySelectorAll('textarea'))inp.value='';setMsg('Login accepted.');await refresh();}catch(err){setMsg(err.message,true);}};
$('token-form').onsubmit=async(e)=>{e.preventDefault();const raw=$('token').value.trim();if(!raw)return;try{await json('/api/token',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({access_token:raw})});$('token').value='';setMsg('Token accepted.');await refresh();}catch(err){setMsg(err.message,true);}};
refresh().catch(e=>setMsg('Unable to read local API: '+e.message,true));
